/// <summary>
/// Data area Id 
/// </summary>
/// <param name = "_dataAreaId"></param>
/// <returns></returns>
[DataMember(extendedTypeStr(dataAreaId))]
public str parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    if (!prmIsDefault(_dataAreaId))
    {
        dataAreaId = _dataAreaId;
    }
    return dataAreaId;
}

/// <summary>
